import { DomainError } from "./errors";

export const orderStates = ["placed", "paid", "packed", "shipped", "delivered"] as const;
export type OrderState = (typeof orderStates)[number];

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export class Order {
  private currentState: OrderState = "placed";
  private isCancelled = false;

  public constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly lines: readonly OrderLine[],
  ) {
    if (!id.trim()) throw new DomainError("An order id is required.");
    if (!customerId.trim()) throw new DomainError("A customer id is required.");
    if (lines.length === 0) throw new DomainError("An order must contain at least one item.");
  }

  public get state(): OrderState {
    return this.currentState;
  }

  public get cancelled(): boolean {
    return this.isCancelled;
  }

  public advanceTo(nextState: OrderState): void {
    if (this.isCancelled) throw new DomainError("A cancelled order cannot change state.");
    const currentIndex = orderStates.indexOf(this.currentState);
    if (orderStates[currentIndex + 1] !== nextState) {
      throw new DomainError(`Order '${this.id}' can only move from ${this.currentState} to ${orderStates[currentIndex + 1] ?? "no further state"}.`);
    }
    this.currentState = nextState;
  }

  public cancel(): void {
    if (this.isCancelled) throw new DomainError("Order is already cancelled.");
    if (this.currentState === "shipped" || this.currentState === "delivered") {
      throw new DomainError("An order cannot be cancelled after it has been shipped.");
    }
    this.isCancelled = true;
  }
}

